CONSTRAINT webhook_subscription.webhook_subscription_token_id_not_null NOT NULL token_id
CONSTRAINT webhook_subscription.webhook_subscription_url_check CHECK ((url ~ '^https://'::text))
CONSTRAINT webhook_subscription.webhook_subscription_url_not_null NOT NULL url

