-- triggers
TRIGGER CREATE TRIGGER agent_run_ops_guard BEFORE INSERT ON public.agent_run FOR EACH ROW EXECUTE FUNCTION ops_kill_level_guard('2')
TRIGGER CREATE TRIGGER approval_change_guard_update BEFORE UPDATE ON public.approval FOR EACH ROW EXECUTE FUNCTION approval_change_guard()
TRIGGER CREATE TRIGGER approval_enforce_insert BEFORE INSERT ON public.approval FOR EACH ROW EXECUTE FUNCTION approval_enforce()
TRIGGER CREATE TRIGGER approval_ops_guard BEFORE INSERT ON public.approval FOR EACH ROW EXECUTE FUNCTION ops_execution_guard()
TRIGGER CREATE TRIGGER audit_checkpoint_no_truncate BEFORE TRUNCATE ON public.audit_checkpoint FOR EACH STATEMENT EXECUTE FUNCTION audit_event_reject_change()
TRIGGER CREATE TRIGGER audit_checkpoint_no_update_delete BEFORE DELETE OR UPDATE ON public.audit_checkpoint FOR EACH ROW EXECUTE FUNCTION audit_event_reject_change()
TRIGGER CREATE TRIGGER audit_event_no_truncate BEFORE TRUNCATE ON public.audit_event FOR EACH STATEMENT EXECUTE FUNCTION audit_event_reject_change()
TRIGGER CREATE TRIGGER audit_event_no_update_delete BEFORE DELETE OR UPDATE ON public.audit_event FOR EACH ROW EXECUTE FUNCTION audit_event_reject_change()
TRIGGER CREATE TRIGGER break_glass_enforce_write BEFORE INSERT OR DELETE OR UPDATE ON public.break_glass FOR EACH ROW EXECUTE FUNCTION break_glass_enforce()
TRIGGER CREATE TRIGGER break_glass_no_truncate BEFORE TRUNCATE ON public.break_glass FOR EACH STATEMENT EXECUTE FUNCTION audit_event_reject_change()
TRIGGER CREATE TRIGGER control_state_no_delete BEFORE DELETE ON public.control_state FOR EACH ROW EXECUTE FUNCTION ops_control_no_delete()
TRIGGER CREATE TRIGGER control_state_no_truncate BEFORE TRUNCATE ON public.control_state FOR EACH STATEMENT EXECUTE FUNCTION ops_control_no_delete()
TRIGGER CREATE TRIGGER control_state_ops_enforce BEFORE UPDATE ON public.control_state FOR EACH ROW EXECUTE FUNCTION ops_control_enforce()
TRIGGER CREATE TRIGGER effect_enforce_write BEFORE INSERT OR UPDATE ON public.effect FOR EACH ROW EXECUTE FUNCTION effect_enforce()
TRIGGER CREATE TRIGGER effect_ops_guard BEFORE INSERT ON public.effect FOR EACH ROW EXECUTE FUNCTION ops_execution_guard()
TRIGGER CREATE TRIGGER envelope_enforce_write BEFORE INSERT OR DELETE OR UPDATE ON public.envelope FOR EACH ROW EXECUTE FUNCTION envelope_enforce()
TRIGGER CREATE TRIGGER envelope_no_truncate BEFORE TRUNCATE ON public.envelope FOR EACH STATEMENT EXECUTE FUNCTION audit_event_reject_change()
TRIGGER CREATE TRIGGER execution_token_enforce_write BEFORE INSERT OR UPDATE ON public.execution_token FOR EACH ROW EXECUTE FUNCTION execution_token_enforce()
TRIGGER CREATE TRIGGER execution_token_ops_guard BEFORE INSERT OR UPDATE ON public.execution_token FOR EACH ROW EXECUTE FUNCTION ops_execution_guard()
TRIGGER CREATE TRIGGER job_ingest_ops_guard BEFORE INSERT ON public.job FOR EACH ROW EXECUTE FUNCTION ops_kill_level_guard('3')
TRIGGER CREATE TRIGGER llm_call_no_truncate BEFORE TRUNCATE ON public.llm_call FOR EACH STATEMENT EXECUTE FUNCTION llm_call_append_only()
TRIGGER CREATE TRIGGER llm_call_no_update_delete BEFORE DELETE OR UPDATE ON public.llm_call FOR EACH ROW EXECUTE FUNCTION llm_call_append_only()
TRIGGER CREATE TRIGGER ops_kill_restore_enforce_write BEFORE INSERT OR UPDATE ON public.ops_kill_restore FOR EACH ROW EXECUTE FUNCTION ops_restore_enforce()
TRIGGER CREATE TRIGGER proposal_authority_guard_write BEFORE INSERT OR UPDATE ON public.proposal FOR EACH ROW EXECUTE FUNCTION proposal_authority_guard()
TRIGGER CREATE TRIGGER proposal_ops_guard BEFORE INSERT ON public.proposal FOR EACH ROW EXECUTE FUNCTION ops_kill_level_guard('3')

